async function syncMetadata(eventId,attempt=0){const custom=activeCustomMap(),iof=iofSummary();const meta={premiumSchemaVersion:4,raceType:state.draft.raceType,description:String(state.draft.description||"").trim(),mapSelection:{layer:state.draft.mapLayer,label:mapLabel(state.draft.mapLayer),workCenter:{lat:Number(state.draft.mapCenterLat),lon:Number(state.draft.mapCenterLon),zoom:Number(state.draft.mapZoom)||13},customMap:state.draft.mapLayer==="custom"?{id:custom?.id||state.draft.customMapId||"",name:custom?.name||state.draft.customMapName||"",format:custom?.format||state.draft.customMapFormat||""}:null},scheduledStartAt:new Date(state.draft.startAt).toISOString(),scheduledEndAt:new Date(state.draft.endAt).toISOString(),timeZone:state.draft.timeZone||"Europe/Madrid",meetingPoint:{name:String(state.draft.locationName||"").trim(),lat:validCoords()?Number(state.draft.lat):null,lon:validCoords()?Number(state.draft.lon):null,mapsUrl:mapsUrl()},premiumControlCount:Number(state.draft.controlCount)||0,premiumIofComplete:iof.allComplete,premiumRouteCount:routeTargetCount(),premiumControlsPerRoute:controlsPerRoute(),updatedAtLocal:new Date().toISOString()};try{localStorage.setItem(META_PREFIX+eventId,JSON.stringify(meta))}catch(_){ }if(!navigator.onLine)return false;try{const auth=globalThis.MILITOPO_V2_AUTH||state.auth;if(!auth?.uid)return false;const {firestore}=await globalThis.MILITOPO_V2.firebase();await setDoc(doc(firestore,"events",eventId),{...meta,ownerUid:String(auth.uid),updatedAt:serverTimestamp()},{merge:true});return true}catch(error){console.warn("[MILITOPO Premium Builder] metadata",error);if(attempt<2){await new Promise(r=>setTimeout(r,800*(attempt+1)));return syncMetadata(eventId,attempt+1)}return false}}
function applyLegacyBasics(){const name=document.getElementById("eventName"),count=document.getElementById("participantCount"),controls=document.getElementById("controlCount"),per=document.getElementById("controlsPerRoute"),routes=document.getElementById("maxUniqueRoutes");if(name){name.value=state.draft.name.trim();name.dispatchEvent(new Event("input",{bubbles:true}));name.dispatchEvent(new Event("change",{bubbles:true}))}if(count){count.value=String(Math.max(1,Math.min(100,Number(state.draft.participantCount)||1)));count.dispatchEvent(new Event("change",{bubbles:true}))}if(controls){controls.value=String(Math.max(1,Math.min(80,Number(state.draft.controlCount)||legacyControlCount())));controls.dispatchEvent(new Event("change",{bubbles:true}))}if(per)per.value=String(controlsPerRoute());if(routes)routes.value=String(routeTargetCount())}
function applySelectedPlan(){try{globalThis.MILITOPO_MAP_CONTROL?.switchLayer?.(state.draft.mapLayer)}catch(e){console.warn("[MILITOPO Premium Builder] capa",e)}}
async function finishBase(){for(let i=0;i<7;i++){const err=validateStep(i);if(err){state.step=i;render();notify(err);return}}if(state.busy)return;state.busy=true;footer();try{const id=String(state.eventId||bridge()?.shell?.current?.().eventId||"").trim();if(!id){notify("No hay un borrador cargado.");return}applyLegacyBasics();r2()?.configureManualRoutes?.(routeTargetCount(),controlsPerRoute());applySelectedPlan();const ok=await syncMetadata(id);clearDraft();close();setTimeout(()=>{notify(ok?"Diseño Premium guardado. El siguiente bloque será el itinerario real.":"Diseño guardado en el dispositivo. Se sincronizará cuando vuelva la conexión.");try{bridge()?.shell?.manager({source:"premium-builder-p2c",eventId:id})}catch(_){ }globalThis.dispatchEvent(new CustomEvent("militopo:premium-builder-p2c-complete",{detail:{eventId:id}}))},120)}finally{state.busy=false;if(state.opened)footer()}}
function reuse(){syncInputs();close();bridge()?.shell?.races?.();notify("Selecciona una carrera anterior y utiliza REUTILIZAR.")}
function onInput(event){
  const target=event?.target;
  if(target?.matches?.("[data-mpb-iof-field]")&&event.type==="change"){const result=r2()?.updateIof?.(target.dataset.mpbIofPoint,target.dataset.mpbIofField,target.value);if(!result?.ok)notify(result?.error||"No se pudo actualizar la descripción IOF.");refreshControlsUi();return}
  if(target?.id==="mpbCustomMapLibrary"&&event.type==="change"){selectCustomMap(target.value);return}
  syncInputs();
  if(event?.type==="change"&&(state.step===3||state.step===4)){setTimeout(render,0);return}
  if(event?.type==="change"&&state.step===6&&(target?.id==="mpbRouteCount"||target?.id==="mpbControlsPerRoute")){r2()?.configureManualRoutes?.(routeTargetCount(),controlsPerRoute());ensureRouteSelection();loadRouteDraft(state.selectedRouteId);setTimeout(render,0)}
}
async function onClick(e){
  const t=e.target.closest("button,a");if(!t)return;
  if(t.matches("[data-mpb-close]")){syncInputs();close();return}if(t.matches("[data-mpb-next]")){await next();return}if(t.matches("[data-mpb-back]")){back();return}if(t.matches("[data-mpb-jump]")){await jump(t.dataset.mpbJump);return}
  if(t.matches("[data-mpb-type]")){state.draft.raceType=t.dataset.mpbType;saveDraft();render();return}if(t.matches("[data-mpb-reuse]")){reuse();return}if(t.matches("[data-mpb-layer]")){chooseLayer(t.dataset.mpbLayer);return}if(t.matches("[data-mpb-import-plan]")){importPlan();return}if(t.matches("[data-mpb-map-geolocate]")){geolocateWorkArea();return}if(t.matches("[data-mpb-location-search]")){await searchLocation();return}if(t.matches("[data-mpb-geolocate]")){geolocate();return}if(t.matches("[data-mpb-use-work-center]")){useWorkCenter();return}
  if(t.matches("[data-mpb-point]")){state.selectedControlId=t.dataset.mpbPoint;refreshControlsUi();return}if(t.matches("[data-mpb-control-count]")){changeControlCount(Number(t.dataset.mpbControlCount));return}if(t.matches("[data-mpb-clear-point]")){clearSelectedControl();return}if(t.matches("[data-mpb-fit-controls]")){fitControls();return}if(t.matches("[data-mpb-iof-save-next]")){saveIofAndNext(t.dataset.mpbIofSaveNext);return}if(t.matches("[data-mpb-iof-pending]")){r2()?.setIofComplete?.(t.dataset.mpbIofPending,false);refreshControlsUi();return}
  if(t.matches("[data-mpb-route]")){loadRouteDraft(t.dataset.mpbRoute);render();return}if(t.matches("[data-mpb-route-control]")){toggleRouteControl(t.dataset.mpbRouteControl);return}if(t.matches("[data-mpb-save-route]")){await saveCurrentRoute();return}if(t.matches("[data-mpb-finish]")){await finishBase();return}
}
function open(opts={}){if(!canManage())return false;ensure();const ctx=bridge()?.shell?.current?.()||{};state.mode=opts.resumeCurrent?"resume":"create";state.eventId=state.mode==="resume"?String(opts.eventId||ctx.eventId||"").trim():"";if(state.mode==="resume"&&!state.eventId){notify("Carga una carrera antes de continuar la preparación.");return false}state.draft=state.mode==="resume"?hydrateExisting(state.eventId):(opts.fresh?freshDraft():readDraft());if(opts.fresh&&state.mode==="create"){clearDraft(DRAFT_KEY);saveDraft()}const requested=Number(opts.step);state.step=Number.isFinite(requested)?Math.max(0,Math.min(steps.length-1,requested)):(state.mode==="resume"?suggestedResumeStep():0);const s=snapshot(),firstPending=controlOrder(s).find(p=>!pointPlaced(p)||!r2()?.getIofModel?.(p.id)?.complete);state.selectedControlId=firstPending?.id||s?.selectedPointId||"START";state.selectedRouteId=routeId(1);loadRouteDraft(state.selectedRouteId);state.root.classList.add("is-open");state.root.setAttribute("aria-hidden","false");document.body.classList.add("militopo-premium-builder-open");state.opened=true;render();return true}
function resumeCurrent(){return open({resumeCurrent:true})}
function close(){destroyMaps();if(!state.root)return;state.root.classList.remove("is-open");state.root.setAttribute("aria-hidden","true");document.body.classList.remove("militopo-premium-builder-open");state.opened=false}

premium.register("event-builder",Object.freeze({open,resumeCurrent,close,isOpen:()=>state.opened,getDraft:()=>Object.freeze({...state.draft})}),{version:"p2c4",purpose:"guided-event-creation-scroll-actions-location-picker-controls-center"});
globalThis.addEventListener("militopo:v2-auth-ready",e=>{state.auth=e.detail||globalThis.MILITOPO_V2_AUTH||null;if(!canManage())close()});
globalThis.addEventListener("militopo:v2-orientation-import",e=>{const d=e.detail||{};state.importState={message:d.message||d.stage||"Procesando plano…",state:d.state||"progress"};updateImportStatus();if(d.state==="success"){const c=d.map||activeCustomMap();state.draft.mapLayer="custom";state.draft.customMapId=c?.id||"";state.draft.customMapName=c?.name||d.fileName||"Plano propio";state.draft.customMapFormat=c?.format||"";if(c?.bounds&&globalThis.L){const b=L.latLngBounds(c.bounds),m=b.getCenter();setWorkCenter(m.lat,m.lng,14,true)}saveDraft();if(state.opened&&state.step===2)setTimeout(render,40)}});
globalThis.addEventListener("militopo:v2-orientation-custom-map",e=>{if(!state.opened||state.step!==2)return;const c=e.detail?.map;if(!c)return;state.draft.customMapId=c.id||"";state.draft.customMapName=c.name||"";state.draft.customMapFormat=c.format||"";saveDraft()});
globalThis.addEventListener("militopo:premium-controls-updated",()=>{if(state.opened&&state.step===5)setTimeout(refreshControlsUi,20)});
globalThis.addEventListener("militopo:premium-iof-updated",()=>{if(state.opened&&state.step===5)setTimeout(refreshControlsUi,20)});
globalThis.addEventListener("militopo:r2-route-updated",()=>{if(state.opened&&state.step===6)setTimeout(render,20)});
globalThis.addEventListener("online",()=>{const id=String(bridge()?.shell?.current?.().eventId||"");if(id&&state.draft)syncMetadata(id)});
